const body = $input.first().json.body || $input.first().json || {};
const messageText = (body.messageText || body.message || '').trim();
const senderPhone = body.senderPhone || body.phone || 'Unknown';
const senderName = body.senderName || body.name || 'Valued Patient';
const eventType = body.event || 'whatsapp_message';
const session = body.session || {};

// 1. Name Extraction / Normalization
let patientName = session.patientName || senderName;
const nameMatch = messageText.match(/(?:my name is|i am|this is|call me)\s+([a-zA-Z\s]{2,25})/i);
if (nameMatch && nameMatch[1]) {
  patientName = nameMatch[1].trim();
}

// 2. Emergency & Pain Detection
const isEmergency = /pain|emergency|bleeding|swelling|broken|ache|severe|trauma|urgent|infection|fell|cracked/i.test(messageText);

// 3. Service Detection
let service = session.service || 'General Dental Consultation & Checkup';
if (isEmergency) {
  service = 'Emergency Toothache / Acute Dental Care';
} else if (/clean|whitening|hygiene|scale/i.test(messageText)) {
  service = 'Routine Cleaning & Preventative Care';
} else if (/filling|cavity|crown|implant/i.test(messageText)) {
  service = 'Restorative Dentistry / Filling & Crown';
} else if (/brace|aligner|invisalign/i.test(messageText)) {
  service = 'Orthodontics & Teeth Alignment';
}

// 4. Time Detection
let detectedTime = session.preferredTime || '';
if (/today|urgent|now|asap/i.test(messageText)) {
  detectedTime = 'Today (Immediate Walk-In / Triage)';
} else if (/tomorrow.*afternoon|afternoon/i.test(messageText)) {
  detectedTime = 'Tomorrow Afternoon (2:30 PM)';
} else if (/tomorrow.*morning|morning/i.test(messageText)) {
  detectedTime = 'Tomorrow Morning (10:00 AM)';
} else if (/tomorrow/i.test(messageText)) {
  detectedTime = 'Tomorrow (Flexible Slot)';
} else if (/evening/i.test(messageText)) {
  detectedTime = 'Tomorrow Evening (5:00 PM)';
}

// 5. State Machine & Multi-Turn Logic
const currentStage = session.stage || 'INIT';
let nextStage = currentStage;
let isBooked = false;
let autoReply = '';

// Check if user is confirming or agreeing
const isConfirming = /yes|confirm|sure|okay|ok|yep|yeah|book it|go ahead|please do/i.test(messageText);
const isGreetingOnly = /^(hi|hello|hey|salam|assalam|aoa|good morning|good afternoon|good evening)[\s!.]*$/i.test(messageText);

if (isEmergency) {
  nextStage = 'EMERGENCY_CONFIRMED';
  isBooked = true;
  detectedTime = detectedTime || 'Today (Immediate Walk-In)';
  autoReply = `🚨 Urgent Care Notice: Hi ${patientName}! Our clinical triage has flagged your case as HIGH PRIORITY / EMERGENCY. Please walk directly into our emergency clinic at 123 Healthcare Blvd. Our on-duty dentist is being alerted right now. We are ready for you!`;

} else if (currentStage === 'BOOKED') {
  if (/where|location|address/i.test(messageText)) {
    autoReply = `We are located at 123 Healthcare Blvd, Medical District. Your appointment is already confirmed with Dr. Sarah for ${detectedTime || 'Tomorrow Morning'}!`;
  } else if (/fee|cost|price|charges/i.test(messageText)) {
    autoReply = `Our standard consultation is $50 / Rs. 1,500, which includes a comprehensive digital exam. Your slot is locked in for ${detectedTime || 'Tomorrow Morning'}!`;
  } else if (/cancel|reschedule/i.test(messageText)) {
    nextStage = 'AWAITING_TIME';
    isBooked = false;
    autoReply = `No problem, ${patientName}. Would you prefer to switch to a morning or afternoon slot on another day?`;
  } else {
    autoReply = `Thank you, ${patientName}! Your appointment for ${service} on ${detectedTime || 'Tomorrow Morning'} is already confirmed. Let us know if you need anything else before your visit!`;
  }

} else if (currentStage === 'AWAITING_CONFIRMATION' && (isConfirming || detectedTime)) {
  nextStage = 'BOOKED';
  isBooked = true;
  autoReply = `🎉 You're all set, ${patientName}! Your appointment with Dr. Sarah at Apex Dental Clinic is officially confirmed for ${detectedTime || 'Tomorrow Morning (10:00 AM)'} for ${service}.\n\n📍 Location: 123 Healthcare Blvd\nWe have reserved your spot. See you then!`;

} else if (detectedTime && (currentStage === 'AWAITING_TIME' || currentStage === 'GREETED' || currentStage === 'INIT')) {
  nextStage = 'BOOKED';
  isBooked = true;
  autoReply = `🎉 Perfect, ${patientName}! Your appointment with Dr. Sarah at Apex Dental Clinic is officially confirmed for ${detectedTime} for ${service}.\n\n📍 Location: 123 Healthcare Blvd\nWe have reserved your spot on our calendar. See you then!`;

} else if (isGreetingOnly || currentStage === 'INIT' || eventType === 'whatsapp_missed_call') {
  nextStage = 'AWAITING_TIME';
  isBooked = false;
  autoReply = `Hi ${patientName}! This is Sarah from Apex Dental Clinic. We noticed we missed your call — sorry for the inconvenience!\n\nAre you experiencing any dental pain, or would you like to schedule a routine cleaning/checkup? We have openings this week — would morning or afternoon suit you best?`;

} else {
  nextStage = 'AWAITING_TIME';
  isBooked = false;
  autoReply = `Got it, ${patientName}! We can definitely help you with ${service}. We have slots open tomorrow — would you prefer a morning (10:00 AM) or afternoon (2:30 PM) appointment?`;
}

// 6. Google Sheets Payload Formatting
const triageStatus = isEmergency 
  ? 'HIGH PRIORITY / EMERGENCY (WHATSAPP RECOVERY)' 
  : 'CONFIRMED BOOKING (WHATSAPP)';
const notes = isEmergency 
  ? `Sub-60s Auto-Recovery: Urgent dental emergency reported: "${messageText.slice(0, 100)}"` 
  : `WhatsApp Multi-Turn Booking: Confirmed ${service} for ${detectedTime || 'Tomorrow Morning'}.`;
const safePhone = String(senderPhone).startsWith('+') ? `'${senderPhone}` : String(senderPhone);

const updatedSession = {
  patientName: patientName,
  senderPhone: senderPhone,
  service: service,
  preferredTime: detectedTime || 'Tomorrow Morning (10:00 AM)',
  stage: nextStage,
  isBooked: isBooked,
  isEmergency: isEmergency,
  lastUpdated: new Date().toISOString()
};

return {
  json: {
    'TIMESTAMP': new Date().toLocaleString(),
    'PATIENT NAME': patientName,
    'PHONE NUMBER': safePhone,
    'SERVICE / REASON': service,
    'PREFERRED TIME': detectedTime || 'Tomorrow Morning (10:00 AM)',
    'TRIAGE STATUS': triageStatus,
    'NOTES': notes,
    'reply': autoReply,
    'isBooked': isBooked,
    'isEmergency': isEmergency,
    'updatedSession': updatedSession
  }
};

const item = $input.first().json;
return {
  json: {
    'TIMESTAMP': item['TIMESTAMP'],
    'PATIENT NAME': item['PATIENT NAME'],
    'PHONE NUMBER': item['PHONE NUMBER'],
    'SERVICE / REASON': item['SERVICE / REASON'],
    'PREFERRED TIME': item['PREFERRED TIME'],
    'TRIAGE STATUS': item['TRIAGE STATUS'],
    'NOTES': item['NOTES']
  }
};
